'use client';
const require_tabs = require("./tabs.cjs");
const require_tabs_list = require("./tabs-list.cjs");
const require_tabs_panel = require("./tabs-panel.cjs");
const require_tabs_tab = require("./tabs-tab.cjs");
//#region src/components/tabs/index.ts
/**
* Display a group of tabs that can be toggled between.
*
* @example
* <Tabs onChange={(value) => console.log(value)}>
*   <Tabs.List>
*     <Tabs.Tab value='1'>Tab 1</Tabs.Tab>
*     <Tabs.Tab value='2'>Tab 2</Tabs.Tab>
*     <Tabs.Tab value='3'>Tab 3</Tabs.Tab>
*   </Tabs.List>
*   <Tabs.Panel value='1'>content 1</Tabs.Panel>
*   <Tabs.Panel value='2'>content 2</Tabs.Panel>
*   <Tabs.Panel value='3'>content 3</Tabs.Panel>
* </Tabs>
*/
const TabsComponent = Object.assign(require_tabs.Tabs, {
	List: require_tabs_list.TabsList,
	Tab: require_tabs_tab.TabsTab,
	Panel: require_tabs_panel.TabsPanel
});
TabsComponent.Tab.displayName = "Tabs.Tab";
TabsComponent.List.displayName = "Tabs.List";
TabsComponent.Panel.displayName = "Tabs.Panel";
//#endregion
exports.Tabs = TabsComponent;
exports.TabsList = require_tabs_list.TabsList;
exports.TabsPanel = require_tabs_panel.TabsPanel;
exports.TabsTab = require_tabs_tab.TabsTab;
